INSERT INTO `mails_template` VALUES (227,'MAIL_SOL_APROBACION',45,'Solicitud de Aprobación','<h2>Solicitud de Aprobación</h2><p>Se generó una solicitud de cambio de estado para el #TIPO_PROG_PROY# \"#NOMBRE_PROG_PROY#\".</p><p>#ORGANISMO_NOMBRE#<br />#ORGANISMO_DIRECCION#</p>',0),(228,'MAIL_CAMBIO_CONTRASENIA',45,'Cambio de contraseña en SIGES','<p> 	Estimado #NOMBRE#, para cambiar su contrase&ntilde;a en SIGES haga clic en el enlace</p> \n<p> 	<a href=\"#URL_SISTEMA#\">Cambiar contrase&ntilde;a</a></p>\n<p> 	Este link vence en breves minutos, en caso de demoras, deberÃ¡ repetir el proceso de reseteo de clave</p>\n',0),(229,'MAIL_CAMBIO_ESTADO',45,'Programa / Proyecto cambió de fase.','<h2>Cambio de Fase</h2><p>El #TIPO_PROG_PROY# #ID_PROG_PROY# \"#NOMBRE_PROG_PROY#\" cambió de fase a #FASE_PROG_PROY#.</p><p>#ORGANISMO_NOMBRE#<br />#ORGANISMO_DIRECCION#</p>',0),(230,'MAIL_PROG_PROY_PENDIENTE',45,'Pendiente de aprobación.','<h2>Pendiente de aprobación</h2><p>El #TIPO_PROG_PROY# #ID_PROG_PROY# \"#NOMBRE_PROG_PROY#\" esta pendiente de aprobación.</p><p>#ORGANISMO_NOMBRE#<br />#ORGANISMO_DIRECCION#</p>',0),(231,'MAIL_NVO_USUARIO',45,'Usuario SIGES.','<h2>Usuario creado</h2><p>Se ha creado el usuario #USU_MAIL# cuya clave es #USU_PASSWORD#, para ingresar al sistema de SIGES.</p><p>#ORGANISMO_NOMBRE#<br />#ORGANISMO_DIRECCION#</p>',0),(237,'MAIL_SOL_APROBACION',47,'Solicitud de Aprobación','<h2>Solicitud de Aprobación</h2><p>Se generó una solicitud de cambio de estado para el #TIPO_PROG_PROY# \"#NOMBRE_PROG_PROY#\".</p><p>#ORGANISMO_NOMBRE#<br />#ORGANISMO_DIRECCION#</p>',0),(238,'MAIL_CAMBIO_CONTRASENIA',47,'Cambio de contraseña en SIGES','<p> 	Estimado #NOMBRE#, para cambiar su contrase&ntilde;a en SIGES haga clic en el enlace</p> \n<p> 	<a href=\"#URL_SISTEMA#\">Cambiar contrase&ntilde;a</a></p>\n<p> 	Este link vence en breves minutos, en caso de demoras, deberÃ¡ repetir el proceso de reseteo de clave</p>\n',0),(239,'MAIL_CAMBIO_ESTADO',47,'Programa / Proyecto cambió de fase.','<h2>Cambio de Fase</h2><p>El #TIPO_PROG_PROY# #ID_PROG_PROY# \"#NOMBRE_PROG_PROY#\" cambió de fase a #FASE_PROG_PROY#.</p><p>#ORGANISMO_NOMBRE#<br />#ORGANISMO_DIRECCION#</p>',0),(240,'MAIL_PROG_PROY_PENDIENTE',47,'Pendiente de aprobación.','<h2>Pendiente de aprobación</h2><p>El #TIPO_PROG_PROY# #ID_PROG_PROY# \"#NOMBRE_PROG_PROY#\" esta pendiente de aprobación.</p><p>#ORGANISMO_NOMBRE#<br />#ORGANISMO_DIRECCION#</p>',0),(241,'MAIL_NVO_USUARIO',47,'Usuario SIGES.','<h2>Usuario creado</h2><p>Se ha creado el usuario #USU_MAIL# cuya clave es #USU_PASSWORD#, para ingresar al sistema de SIGES.</p><p>#ORGANISMO_NOMBRE#<br />#ORGANISMO_DIRECCION#</p>',0),(242,'MAIL_SOL_REPLANIFICACION',45,'Solicitud de ReplanificaciÃ³n','<h2>   Solicitud de ReplanificaciÃ³n</h2> <p>   Se generÃ³ una solicitud de replanificaciÃ³n para el #TIPO_PROG_PROY# &quot;#NOMBRE_PROG_PROY#&quot;.</p> <div>   #ORGANISMO_NOMBRE#</div> <div>  #ORGANISMO_DIRECCION#</div> <div>   #URL_SISTEMA#</div>',0),(243,'MAIL_SOL_REPLANIFICACION',47,'Solicitud de ReplanificaciÃ³n','<h2>   Solicitud de ReplanificaciÃ³n</h2> <p>   Se generÃ³ una solicitud de replanificaciÃ³n para el #TIPO_PROG_PROY# &quot;#NOMBRE_PROG_PROY#&quot;.</p> <div>   #ORGANISMO_NOMBRE#</div> <div>  #ORGANISMO_DIRECCION#</div> <div>   #URL_SISTEMA#</div>',0);
