INSERT INTO `proyectos` VALUES (2,47,2,NULL,NULL,352,1289,1290,1289,1288,NULL,NULL,3,2,2,0,'<p> <span>Existen 63 sitios diferentes en la Administración Central, con estructura heterogénea que dificultan el acceso homogeinizado a contenidos, incrementando costos operativos y generando una experiencia de usuario confusa. Se propone disponibilizar un <em><strong>Portal del Estado Único, promoviendo la armonía en los mensajes y el vínculo cercano del Estado con las personas.</strong></em></span></p>','<p> <span>Disponer de un Portal del Estado único para comunicar, informar y acercarse a las personas; con una imagen de gobierno unificada, con una comunicación integrada, y centralizando la infraestructura tecnológica.</span></p> \n<p> <span>Que esté integrado por todas las unidades y programas de OrganismoPorDefecto de la República y cada uno de los Ministerios.</span></p> \n<p> <br> <span><strong><em>Contribuye a:</em></strong><br> - Potenciar la Comunicación de Gobierno<br> - Facilitar la interacción de las personas con el Gobierno<br> - Racionalizar recursos y costos</span></p>','<ul> \n <li> Publicar indicadores sobre la evolución de la eficiencia energética en diferentes sectores de actividad en formato de datos abiertos.</li> \n <li> Desarrollar y publicación de un mapa nacional donde se georeferencien los distintos proyectos de eficiencia energética, los instrumentos de promoción que utilizaron y su localización en el territorio nacional.</li> \n</ul>','<p> - Se actualiza Drupal a nueva versión</p> \n<p> - Hoy se decide subir MRREE</p>',NULL,'Portal Único del Estado',NULL,10,20,1,'2019-11-22 15:42:08.000000','2019-11-22 16:39:40.000000',NULL,NULL,NULL,NULL,NULL,NULL,0,2,NULL,12,'<p> <span><em><strong>El Estado</strong></em>: Incorporando una estrategia de comunicación y una vía tecnológica que le permita organizar y homogeinizar su comunicación con la ciudadanía.</span></p> \n<p> <span><em><strong>El ciudadano:</strong></em> Que contará con una herramienta tecnológica moderna y eficiente.</span></p>','2019-11-22 16:39:40.000000',NULL,NULL);
/*!40000 ALTER TABLE `proyectos` ENABLE KEYS */;
UNLOCK TABLES;

